{{--
    Listbox : un select stylable et composable. Moteur : @flexilla/select,
    piloté par resources/js/plugins/listbox.js.

    Raccourci, avec des props :
    <x-ui.listbox wire:model.live="framework" :options="$frameworks" searchable />

    Composition libre, pièce par pièce :
    <x-ui.listbox wire:model.live="owner">
        <x-ui.listbox.trigger>
            <x-ui.listbox.value placeholder="Choose an owner">
                <span data-bind="initials"></span> <span data-bind="label"></span>
            </x-ui.listbox.value>
        </x-ui.listbox.trigger>
        <x-ui.listbox.content>
            <x-ui.listbox.search />
            <x-ui.listbox.list>
                <x-ui.listbox.item value="alice" data-initials="AJ">…</x-ui.listbox.item>
            </x-ui.listbox.list>
            <x-ui.listbox.empty />
        </x-ui.listbox.content>
    </x-ui.listbox>

    La valeur vit dans Alpine (x-modelable) : wire:model reçoit une chaîne,
    ou un tableau avec `multiple`. Ce que Flexilla modifie est ignoré par
    Livewire ; si les options changent côté serveur, donnez au listbox un
    wire:key qui en dépend.
--}}
@props([
    'name' => null,
    'value' => null,
    'options' => null,
    'optionValue' => 'value',
    'optionLabel' => 'label',
    'optionDescription' => 'description',
    'optionIcon' => 'icon',
    'optionAvatar' => 'avatar',
    'optionDisabled' => 'disabled',
    'optionGroup' => 'group',
    'multiple' => false,
    'searchable' => false,
    'placeholder' => 'Select an option',
    'searchPlaceholder' => 'Search…',
    'emptyText' => 'No results found for “:query”',
    'display' => 'chips',
    'maxChips' => null,
    'countText' => ':count selected',
    'compactText' => ':labels and :count more',
    'removeLabel' => 'Remove :label',
    'clearText' => 'Clear all',
    'label' => null,
    'size' => 'md',
    'disabled' => false,
    'invalid' => false,
    'placement' => 'bottom-start',
])

@php
    $model = $attributes->wire('model')->value();
    // Stable d'un rendu Livewire à l'autre, distinct entre deux champs de la page.
    $id = $attributes->get('id') ?? 'listbox-'.\Illuminate\Support\Str::slug($name ?? $model ?? 'field').'-'.substr(md5((string) json_encode([$name, $model, $label, $placeholder, $options instanceof \Illuminate\Contracts\Support\Arrayable ? $options->toArray() : $options, (string) $slot])), 0, 6);
    $errorKey = $model ?: ($name ? str_replace(['[]', '[', ']'], ['', '.', ''], $name) : null);
    $isInvalid = $invalid || ($errorKey && isset($errors) && $errors->has($errorKey));
    $display = in_array($display, ['chips', 'count', 'compact'], true) ? $display : 'chips';

    $items = \App\Flexiwind\OptionList::normalize($options, [
        'value' => $optionValue, 'label' => $optionLabel, 'description' => $optionDescription,
        'icon' => $optionIcon, 'avatar' => $optionAvatar, 'disabled' => $optionDisabled, 'group' => $optionGroup,
    ]);

    // Hors Livewire, la valeur de départ vient de `value` ou de old().
    $initial = \App\Flexiwind\OptionList::selected($name ? old(str_replace(['[]', '[', ']'], ['', '.', ''], $name), $value) : $value);

    // Avec un panneau dans le contenu, la composition est la vôtre.
    $composed = str_contains((string) $slot, 'data-select-content');
@endphp

<div data-slot="listbox" data-listbox-id="{{ $id }}" @if ($isInvalid) data-invalid @endif
    x-data="fwListbox(@js([
        'kind' => 'select',
        'multiple' => (bool) $multiple,
        'value' => $multiple ? $initial : ($initial[0] ?? null),
        'name' => $name,
        'disabled' => (bool) $disabled,
    ]))"
    x-modelable="value"
    {{ $attributes->except(['id'])->whereDoesntStartWith('aria-')->class(['group/listbox flex w-full min-w-0 flex-col gap-2']) }}>

    @if ($label)
        <x-ui.label :text="$label" data-listbox-label wire:ignore.self />
    @endif

    @if ($composed)
        {{ $slot }}
    @else
        <x-ui.listbox.trigger :size="$size" :disabled="$disabled" :attributes="$attributes->whereStartsWith('aria-')->merge($isInvalid ? ['aria-invalid' => 'true'] : [])">
            @if ($multiple && $display === 'chips')
                <span class="truncate text-muted-foreground">{{ $placeholder }}</span>
            @else
                <x-ui.listbox.value :mode="$multiple ? $display : 'single'" :placeholder="$placeholder" :count-text="$countText" :compact-text="$compactText" />
            @endif
        </x-ui.listbox.trigger>

        @if ($multiple && $display === 'chips')
            <div class="flex flex-wrap items-center gap-1.5">
                <x-ui.listbox.value mode="chips" placeholder="" :max="$maxChips" :remove-label="$removeLabel" class="contents" />
                <x-ui.listbox.clear class="ms-1">{{ $clearText }}</x-ui.listbox.clear>
            </div>
        @endif

        <x-ui.listbox.content :placement="$placement">
            @if ($searchable)
                <x-ui.listbox.search :placeholder="$searchPlaceholder" />
            @endif
            <x-ui.listbox.list>
                @if ($items !== [])
                    <x-ui.listbox.items :options="$items" />
                @endif
                {{ $slot }}
            </x-ui.listbox.list>
            <x-ui.listbox.empty :empty-text="$emptyText">{{ $empty ?? '' }}</x-ui.listbox.empty>
        </x-ui.listbox.content>
    @endif

    <x-ui.listbox.inputs :name="$name" />
</div>

{{--
    Le déclencheur d'un listbox : l'input, en bouton. Sans contenu, il
    affiche la valeur (<x-ui.listbox.value />) ; avec contenu, tout est à
    vous. Flexilla y pose aria-expanded et aria-controls.
--}}
@aware(['size' => 'md', 'disabled' => false])
@props(['chevron' => true, 'size' => 'md', 'disabled' => false])

@php
    $sizes = ['sm' => 'ui-form-input-sm', 'md' => 'ui-form-input-md', 'lg' => 'ui-form-input-lg'];
@endphp

<button type="button" wire:key="listbox-trigger" wire:ignore.self data-select-trigger @if ($disabled) disabled @endif
    {{ $attributes->class([
        'relative flex w-full min-w-0 items-center gap-2 text-start text-sm text-foreground',
        $sizes[$size] ?? $sizes['md'],
        'rounded-ui border border-border-input bg-background',
        'outline outline-transparent outline-offset-0 ring-3 ring-transparent ring-offset-1 ring-offset-transparent transition-all duration-200 ease-linear',
        'enabled:hover:border-muted-foreground/30 focus:border-transparent focus:outline-(--ui-input-focus-outline) focus:ring-(--focus-ring)',
        'aria-expanded:border-primary/70 aria-expanded:ring-(--focus-ring)',
        'group-data-invalid/listbox:border-(--ui-input-invalid-outline) group-data-invalid/listbox:ring-(--ui-input-invalid-outline)/20',
        'disabled:cursor-not-allowed disabled:bg-muted disabled:opacity-50',
    ]) }}>
    @if ($slot->isEmpty())
        <x-ui.listbox.value />
    @else
        {{ $slot }}
    @endif
    @if ($chevron)
        <span aria-hidden="true" data-slot="chevron" class="-me-1 ms-auto flex size-4 shrink-0 text-muted-foreground iconify ph--caret-up-down"></span>
    @endif
</button>

{{-- Un bouton qui vide la sélection. Caché tant qu'il n'y a rien à vider. --}}
<button type="button" data-listbox-clear wire:ignore x-cloak x-show="hasValue && !disabled"
    {{ $attributes->class(['rounded-[calc(var(--radius-ui)-var(--spacing))] text-xs font-medium text-primary hover:underline focus-visible:outline-2 focus-visible:outline-(--ui-input-focus-outline)']) }}>
    @if ($slot->isEmpty())
        Clear all
    @else
        {{ $slot }}
    @endif
</button>

{{--
    La liste des options : une grille dont chaque option est une sous-grille,
    comme le dropdown, pour que coches et libellés s'alignent.

    Avec une recherche Livewire (`search` sur l'autocomplete), les options
    sont aussi écrites dans un bloc caché que Livewire met à jour : le plugin
    les recopie ici, où Flexilla travaille à l'abri des re-rendus.
--}}
@aware(['search' => null])
@props(['search' => null])

<div wire:key="listbox-list" data-listbox-list wire:ignore x-show="!hint"
    @if ($search) wire:loading.class="opacity-55" wire:target="{{ $search }}" @endif
    {{ $attributes->class([
        'grid max-h-72 min-h-0 grid-cols-[auto_1fr] gap-y-1 overflow-y-auto overscroll-contain transition-opacity',
        '*:[[role=group]+[role=group]]:mt-3',
    ]) }}>
    {{-- Flexilla veut au moins une option : celle-ci ne s'affiche jamais. --}}
    <div data-select-item="__fw-none" data-disabled aria-hidden="true" class="hidden!"></div>
    {{ $slot }}
</div>

@if ($search)
    <div hidden data-autocomplete-source>{{ $slot }}</div>
@endif

{{--
    Une option. Écrivez son contenu comme vous voulez :

    <x-ui.listbox.item value="alice" data-initials="AJ">
        <x-ui.listbox.avatar src="…" />
        <x-ui.listbox.label>Alice Johnson</x-ui.listbox.label>
        <x-ui.listbox.description>alice@example.com</x-ui.listbox.description>
    </x-ui.listbox.item>

    Un simple texte devient le libellé. `label` fixe le texte utilisé par la
    recherche et l'affichage de la valeur ; sinon c'est celui de
    <x-ui.listbox.label>, ou tout le texte de l'option. Les attributs data-*
    sont lus par les modèles de <x-ui.listbox.value> (data-bind="initials").
--}}
@props(['value', 'label' => null, 'disabled' => false, 'check' => true])

@php
    $html = (string) $slot;
    $hasLabel = str_contains($html, 'data-slot="label"');
    $isText = ! str_contains($html, '<');

    if ($label === null && $hasLabel && preg_match('/data-slot="label"[^>]*>(.*?)<\/span>/s', $html, $match)) {
        $label = $match[1];
    }

    $text = trim(preg_replace('/\s+/', ' ', html_entity_decode(strip_tags($label ?? $html), ENT_QUOTES)));
@endphp

<div data-select-item="{{ $value }}" data-label="{{ $text }}"
    @if ($disabled) data-disabled aria-disabled="true" @endif
    {{ $attributes->class([
        'dropdown-item-base dropdown-item-base-vars',
        'min-w-0 [--mr-icon:--spacing(2.5)] sm:[--mr-icon:--spacing(2)]',
        'not-has-[[slot=description]]:items-center',
        'group relative cursor-default select-none dropdown-item-radius rounded-dropdown-item text-left',
        'text-base/6 sm:text-sm/6 text-muted-foreground forced-colors:text-[CanvasText]',
        'dropdown-item-grid dropdown-item-icon dropdown-item-keyboard dropdown-item-description dropdown-item-has-description',
        'dropdown-item-label dropdown-item-avatar dropdown-item-force-color dropdown-item-hover dropdown-item-disabled',
        'dropdown-item-selected dropdown-item-selected-icon dropdown-item-selected-avatar-icon dropdown-item-selected-avatar',
        // L'option surlignée au clavier par Flexilla.
        'data-select-highlighted:bg-(--dropdown-item-hover-and-select) data-select-highlighted:text-(--dropdown-item-hover-and-select-fg)',
        'data-disabled:opacity-50',
    ]) }}>
    @if ($check)
        <span aria-hidden="true" data-slot="check-indicator"
            class="mr-1.5 -ml-0.5 hidden group-selected:flex h-lh shrink-0 text-xs text-foreground iconify ph--check-bold invisible group-selected:visible
                group-has-data-[slot=icon]:absolute group-has-data-[slot=icon]:top-1/2 group-has-data-[slot=icon]:right-2.5 group-has-data-[slot=icon]:mr-0 group-has-data-[slot=icon]:-translate-y-1/2
                group-has-data-[slot=avatar]:absolute group-has-data-[slot=avatar]:top-1/2 group-has-data-[slot=avatar]:right-2.5 group-has-data-[slot=avatar]:mr-0 group-has-data-[slot=avatar]:-translate-y-1/2"></span>
    @endif
    @if ($isText)
        <x-ui.listbox.label>{{ $slot }}</x-ui.listbox.label>
    @elseif ($hasLabel || str_contains($html, 'data-slot="'))
        {{ $slot }}
    @else
        {{-- Du HTML libre : il prend la colonne du libellé. --}}
        <span class="col-start-2 min-w-0">{{ $slot }}</span>
    @endif
</div>

{{-- Une icône d'option : une classe Iconify (`name`) ou votre SVG. --}}
@props(['name' => null])

@if ($name)
    <x-ui.icon :name="$name" {{ $attributes->class(['opacity-70']) }} />
@else
    <span slot="icon" data-slot="icon" aria-hidden="true" {{ $attributes->class(['flex size-4 shrink-0 items-center opacity-70']) }}>{{ $slot }}</span>
@endif

{{--
    L'avatar d'une option : une image (`src`), ou ce que vous y mettez
    (des initiales, une pastille de couleur).
--}}
@props(['src' => null, 'alt' => '', 'size' => 'sm'])

@php
    $sizes = ['xs' => 'size-4', 'sm' => 'size-5 sm:size-4', 'md' => 'size-6', 'lg' => 'size-8'];
    $sizeClass = $sizes[$size] ?? $sizes['sm'];
@endphp

@if ($src)
    <img data-slot="avatar" src="{{ $src }}" alt="{{ $alt }}" {{ $attributes->class(['me-(--mr-icon) shrink-0 self-center rounded-full object-cover', $sizeClass]) }}>
@else
    <span data-slot="avatar" aria-hidden="true" {{ $attributes->class(['me-(--mr-icon) inline-flex shrink-0 items-center justify-center self-center rounded-full bg-muted text-[10px] font-semibold text-foreground', $sizeClass]) }}>{{ $slot }}</span>
@endif

{{--
    Un groupe d'options. `label` en fait le titre ; <x-ui.listbox.header>
    permet un titre libre. Il disparaît quand la recherche a masqué toutes
    ses options.
--}}
@props(['label' => null])

@php
    $headingId = $label ? 'listbox-group-'.substr(md5($label.spl_object_id($slot)), 0, 8) : null;
@endphp

<div role="group" @if ($headingId) aria-labelledby="{{ $headingId }}" @endif
    {{ $attributes->class([
        'col-span-full grid grid-cols-subgrid gap-y-1',
        'not-has-[[data-select-item]:not([hidden])]:hidden',
    ]) }}>
    @if ($label)
        <x-ui.listbox.header :id="$headingId">{{ $label }}</x-ui.listbox.header>
    @endif
    {{ $slot }}
</div>

{{--
    Ce qui s'affiche quand la recherche ne trouve rien. <x-ui.listbox.query />
    répète ce qui a été tapé.
--}}
@aware(['emptyText' => 'No results found for “:query”'])
@props(['emptyText' => 'No results found for “:query”'])

<div data-select-empty hidden wire:ignore x-show="!hint" {{ $attributes->class(['px-3 py-1.5 text-sm/6 text-muted-foreground']) }}>
    @if ($slot->isNotEmpty())
        {{ $slot }}
    @else
        {{ \Illuminate\Support\Str::before($emptyText, ':query') }}@if (\Illuminate\Support\Str::contains($emptyText, ':query'))<x-ui.listbox.query />{{ \Illuminate\Support\Str::after($emptyText, ':query') }}@endif
    @endif
</div>

{{-- Les champs cachés d'un formulaire classique : un par valeur. --}}
@props(['name' => null])

@if ($name)
    <div wire:ignore hidden>
        <template x-for="(item, index) in formValues" :key="index">
            <input type="hidden" :name="inputName" :value="item">
        </template>
    </div>
@endif

{{-- Les options passées en tableau ou en Collection, composées avec les mêmes pièces. --}}
@props(['options' => []])

@foreach (\App\Flexiwind\OptionList::groups($options) as $group)
    @if ($group['label'] !== null)
        <x-ui.listbox.group :label="$group['label']">
            @foreach ($group['options'] as $option)
                @include('components.ui.listbox.partials.item', ['option' => $option])
            @endforeach
        </x-ui.listbox.group>
    @else
        @foreach ($group['options'] as $option)
            @include('components.ui.listbox.partials.item', ['option' => $option])
        @endforeach
    @endif
@endforeach

import { Select } from "@flexilla/select";
import { Autocomplete } from "@flexilla/autocomplete";
import { LayerPlugin } from "./layer";

/** L'option fantôme : Flexilla exige au moins une option. */
const NONE = "__fw-none";

/**
 * La copie des résultats serveur vit dans le panneau : ses options portent
 * un autre data-select-id, que Flexilla ignore.
 */
const SOURCE = "__fw-source";

/** Un identifiant par composant de la page, même si Blade en donne deux pareils. */
let sequence = 0;

export function ListboxPlugin(Alpine) {
    LayerPlugin(Alpine);
    Alpine.data("fwListbox", listbox);
}

/**
 * Donne le focus à un élément du panneau dès qu'il peut le prendre :
 * Flexilla affiche le panneau après l'avoir positionné, et un élément
 * encore invisible refuse le focus. Quelques essais suffisent.
 */
function focusWhenShown(resolve, attempts = 20) {
    const element = resolve();

    if (!element) {
        return;
    }

    // Sans défilement : le panneau est positionné, la page ne doit pas sauter.
    element.focus({ preventScroll: true });

    if (document.activeElement !== element && attempts > 0) {
        setTimeout(() => focusWhenShown(resolve, attempts - 1), 25);
    }
}

/** Une URL qu'un modèle peut poser dans src ou href : pas de javascript:. */
function safeUrl(value) {
    return /^(https?:\/\/|\/(?!\/)|#|mailto:|tel:)/i.test(value) ? value : "";
}

/** Un style qu'un modèle peut poser : pas de url(), d'expression() ni d'@import. */
function safeStyle(value) {
    return /url\s*\(|expression\s*\(|@import|javascript:/i.test(value) ? "" : value;
}

/**
 * Remplit un modèle de valeur avec les liaisons de Flexilla. Tout passe par
 * textContent ou des attributs filtrés : une donnée n'est jamais du HTML.
 */
function fill(node, record, onRemove, removeLabel) {
    const all = (selector) => [...(node.matches(selector) ? [node] : []), ...node.querySelectorAll(selector)];

    all("[data-bind]").forEach((element) => {
        element.textContent = record[element.getAttribute("data-bind")] ?? "";
    });

    all("[data-select-label]").forEach((element) => (element.textContent = record.label ?? ""));
    all("[data-select-value]").forEach((element) => (element.textContent = record.value ?? ""));

    for (const attribute of ["src", "href", "alt", "title"]) {
        all(`[data-bind-${attribute}]`).forEach((element) => {
            const raw = record[element.getAttribute(`data-bind-${attribute}`)] ?? "";
            const value = attribute === "src" || attribute === "href" ? safeUrl(raw) : raw;

            if (value) {
                element.setAttribute(attribute, value);
                element.hidden = false;
            } else {
                element.removeAttribute(attribute);

                // Une image sans source ne laisse pas de trou.
                if (attribute === "src") {
                    element.hidden = true;
                }
            }
        });
    }

    all("[data-bind-style]").forEach((element) => {
        const value = safeStyle(record[element.getAttribute("data-bind-style")] ?? "");

        value ? element.setAttribute("style", value) : element.removeAttribute("style");
    });

    all("[data-select-remove]").forEach((button) => {
        if (!button.hasAttribute("aria-label")) {
            button.setAttribute("aria-label", removeLabel.replace(":label", record.label ?? record.value));
        }

        button.addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            onRemove(record.value);
        });
    });
}

function listbox(config = {}) {
    const multiple = Boolean(config.multiple);
    const isAutocomplete = config.kind === "autocomplete";

    // Hors de l'état Alpine : un proxy réactif autour de Flexilla et du DOM n'apporte rien.
    let root = null;
    let key = "";
    let instance = null;
    let syncing = false;
    let resyncQueued = false;
    let refreshQueued = false;
    let previous = [];
    let wasOpen = false;
    let observer = null;
    let searchTimer = null;
    const listeners = [];

    /**
     * Le composant et son panneau. Le panneau vit dans <body> (x-teleport) :
     * on le retrouve par son template, resté dans le composant.
     */
    const scopes = () => [
        root,
        ...[...root.querySelectorAll("template[data-listbox-panel]")].map((template) => template._x_teleport).filter(Boolean),
    ];

    const part = (selector) => {
        for (const scope of scopes()) {
            const found = scope.matches(selector) ? scope : scope.querySelector(selector);

            if (found) {
                return found;
            }
        }

        return null;
    };

    const parts = (selector) => scopes().flatMap((scope) => [...(scope.matches(selector) ? [scope] : []), ...scope.querySelectorAll(selector)]);

    const listen = (target, type, handler, capture = false) => {
        target.addEventListener(type, handler, capture);
        listeners.push(() => target.removeEventListener(type, handler, capture));
    };

    const matches = (query, item) => {
        if (item.value === NONE) {
            return false;
        }

        // Côté serveur, les options reçues sont déjà les résultats.
        if (config.search) {
            return true;
        }

        return !query || (item.label ?? item.value).toLowerCase().includes(query.toLowerCase());
    };

    return {
        value: multiple ? [...(config.value ?? [])] : (config.value ?? null),
        records: {},
        query: "",
        multiple,
        disabled: Boolean(config.disabled),
        inputName: config.name ? config.name + (multiple && !config.name.endsWith("[]") ? "[]" : "") : null,

        init() {
            root = this.$el;
            key = `${root.dataset.listboxId || "listbox"}-${++sequence}`;

            // Le panneau (x-teleport) n'existe qu'une fois les enfants initialisés.
            this.$nextTick(() => this.setup());
        },

        setup() {
            // Copie détachée préparée par Livewire pendant un rendu : rien à brancher.
            if (!root.isConnected) {
                return;
            }

            this.wire();
            this.markSource();
            this.readRecords();
            this.connect();
            this.render();

            this.$watch("value", () => {
                this.push();
                this.render();
            });

            // Entrée choisit une option : sans preventDefault, le navigateur la
            // rejoue en clic sur le déclencheur, qui vient de reprendre le focus,
            // et le panneau se rouvre (ou le formulaire part, depuis l'input).
            // En capture : Flexilla ferme le panneau pendant sa propre écoute.
            for (const scope of scopes()) {
                listen(scope, "keydown", (event) => {
                    if (event.key === "Enter" && instance?.getState().open) {
                        event.preventDefault();
                    }
                }, true);
            }

            listen(root, "click", (event) => {
                if (event.target.closest("[data-listbox-clear]")) {
                    event.preventDefault();
                    this.clear();
                }
            });

            if (isAutocomplete) {
                // En capture : il passe avant Flexilla. Le panneau s'ouvre d'abord :
                // fermé, Flexilla remettrait le libellé choisi par-dessus la saisie.
                listen(root, "input", (event) => {
                    if (!event.target.matches?.("[data-autocomplete-id]")) {
                        return;
                    }

                    if (instance && !instance.getState().open) {
                        instance.open();
                    }

                    this.query = event.target.value;

                    if (config.search) {
                        this.searchServer();
                    }
                }, true);
            }

            const source = part("[data-autocomplete-source]");

            if (config.search && source) {
                observer = new MutationObserver(() => this.queueRefresh());
                // Pas `attributes` : le marquage des options relancerait l'observation.
                observer.observe(source, { childList: true, subtree: true, characterData: true });
            }
        },

        destroy() {
            observer?.disconnect();
            listeners.splice(0).forEach((remove) => remove());
            clearTimeout(searchTimer);
            instance?.cleanup();
            instance = null;
        },

        // ------------------------------------------------------------ lecture

        get values() {
            if (multiple) {
                return Array.isArray(this.value) ? this.value.map(String) : [];
            }

            return this.value === null || this.value === undefined || this.value === "" ? [] : [String(this.value)];
        },

        get hasValue() {
            return this.values.length > 0;
        },

        /** Ce que poste un formulaire : une valeur vide plutôt que rien en mode simple. */
        get formValues() {
            return this.values.length ? this.values : multiple ? [] : [""];
        },

        get canClear() {
            return !this.disabled && (this.query !== "" || (!multiple && this.hasValue));
        },

        /** Le message à la place des options tant que la saisie est trop courte. */
        get hint() {
            if (!isAutocomplete) {
                return "";
            }

            const length = this.query.trim().length;

            if (config.search && length === 0) {
                return config.startText ?? "";
            }

            if (length < (config.minChars ?? 0)) {
                return (config.minCharsText ?? "").replace(":count", config.minChars);
            }

            return "";
        },

        /** Tout ce qu'une option porte : libellé, valeur et ses data-*. */
        record(value) {
            return this.records[value] ?? { value, label: value };
        },

        // ------------------------------------------------------------ pièces

        /** Relie les pièces composées : un identifiant commun, et le libellé à son champ. */
        wire() {
            const content = part("[data-select-content]");
            const field = isAutocomplete
                ? parts("[data-select-input]").find((input) => !content?.contains(input))
                : part("[data-select-trigger]");

            parts("[data-select-trigger], [data-select-content], [data-select-input]").forEach((element) => {
                element.setAttribute("data-select-id", key);
            });

            if (isAutocomplete && field) {
                field.setAttribute("data-autocomplete-id", key);
            }

            // Le libellé du listbox, ou le premier <label> composé sans `for`.
            const label = part("[data-listbox-label]") ?? parts("label").find((element) => !element.htmlFor);

            if (label && field) {
                field.id ||= `${key}-field`;
                label.htmlFor = field.id;
            }
        },

        markSource() {
            part("[data-autocomplete-source]")?.querySelectorAll("[data-select-item]").forEach((element) => {
                element.setAttribute("data-select-id", SOURCE);
            });
        },

        /** Les options en mémoire : ce qu'affiche la valeur, même hors des résultats. */
        readRecords() {
            parts("[data-select-item]").forEach((element) => {
                const value = element.dataset.selectItem;

                if (value === NONE) {
                    return;
                }

                const { selectItem, label, disabled, ...data } = element.dataset;

                this.records[value] = { ...data, value, label: label || element.textContent.trim() || value };
            });
        },

        /** Rend chaque <x-ui.listbox.value> : libellé, puces, lignes, compteur ou liste courte. */
        render() {
            const values = this.values;
            const records = values.map((value) => this.record(value));

            parts("[data-listbox-value]").forEach((container) => {
                const mode = container.dataset.mode || (multiple ? "chips" : "single");
                const template = container.querySelector(":scope > template[data-selected-model]");
                const more = container.querySelector(":scope > template[data-selected-more]");
                const placeholder = container.querySelector(":scope > [data-placeholder]");
                const removeLabel = container.dataset.removeLabel || "Remove :label";

                container.querySelectorAll(":scope > [data-rendered]").forEach((node) => node.remove());

                if (placeholder) {
                    placeholder.hidden = values.length > 0;
                }

                if (!values.length) {
                    return;
                }

                const append = (node) => {
                    node.setAttribute("data-rendered", "");
                    container.insertBefore(node, placeholder);
                };

                const text = (value) => {
                    const span = document.createElement("span");

                    span.className = "truncate";
                    span.textContent = value;
                    append(span);
                };

                const clone = (record) => {
                    const node = template?.content.firstElementChild?.cloneNode(true);

                    if (!node) {
                        return text(record.label);
                    }

                    fill(node, record, (value) => this.remove(value), removeLabel);
                    append(node);
                };

                if (mode === "count") {
                    return text((container.dataset.countText || ":count selected").replace(":count", values.length));
                }

                if (mode === "compact") {
                    const limit = Number(container.dataset.limit) || 2;
                    const labels = records.map((record) => record.label);

                    return text(
                        labels.length <= limit
                            ? labels.join(", ")
                            : (container.dataset.compactText || ":labels and :count more")
                                  .replace(":labels", labels.slice(0, limit).join(", "))
                                  .replace(":count", labels.length - limit),
                    );
                }

                if (mode === "single") {
                    return clone(records[0]);
                }

                const max = Number(container.dataset.max) || 0;

                (max ? records.slice(0, max) : records).forEach(clone);

                if (max && records.length > max) {
                    const node = more?.content.firstElementChild?.cloneNode(true);

                    if (node) {
                        fill(node, { count: String(records.length - max) }, () => {}, removeLabel);
                        append(node);
                    } else {
                        text(`+${records.length - max}`);
                    }
                }
            });
        },

        // ------------------------------------------------------------ actions

        remove(value) {
            this.value = multiple ? this.values.filter((item) => item !== String(value)) : null;
        },

        clear() {
            this.value = multiple ? [] : null;
        },

        clearInput() {
            const input = part("[data-autocomplete-id]");

            input.value = "";
            this.query = "";
            instance?.setSearch("");

            if (!multiple) {
                this.value = null;
            }

            input.focus();
        },

        searchServer() {
            clearTimeout(searchTimer);

            const query = this.query.trim();

            if (query.length > 0 && query.length < (config.minChars ?? 0)) {
                return;
            }

            searchTimer = setTimeout(() => this.$wire?.$set(config.search, query), config.debounce ?? 300);
        },

        // ------------------------------------------------------------ Flexilla

        connect() {
            const options = { multiple, filter: matches, experimental: { teleport: false } };

            instance = isAutocomplete
                ? new Autocomplete(part("[data-autocomplete-id]"), { ...options, searchDebounce: config.search ? 0 : 100 })
                : new Select(part("[data-select-content]"), options);

            this.push();
            instance.subscribe((state) => this.onState(state));
        },

        /** Recrée l'instance après un changement d'options, sans perdre l'ouverture. */
        reconnect() {
            const input = part("[data-autocomplete-id]");
            const reopen = instance?.getState().open || (input && document.activeElement === input);

            instance?.cleanup();
            instance = null;
            wasOpen = false;
            this.connect();

            if (reopen) {
                instance.open();
            }
        },

        queueRefresh() {
            if (refreshQueued) {
                return;
            }

            refreshQueued = true;

            setTimeout(() => {
                refreshQueued = false;

                const list = part("[data-listbox-list]");
                const none = list.querySelector(`[data-select-item="${NONE}"]`);
                this.markSource();

                const fresh = [...part("[data-autocomplete-source]").children].map((node) => {
                    const copy = node.cloneNode(true);

                    [copy, ...copy.querySelectorAll("[data-select-item]")].forEach((element) => {
                        if (element.getAttribute("data-select-id") === SOURCE) {
                            element.removeAttribute("data-select-id");
                        }
                    });

                    return copy;
                });

                list.replaceChildren(...[none, ...fresh].filter(Boolean));
                this.readRecords();
                this.reconnect();
                this.render();
            });
        },

        /** Alpine → Flexilla : coche ce qui est choisi parmi les options affichées. */
        push() {
            if (!instance) {
                return;
            }

            const want = this.values;
            const have = instance.getState().selectedValues;

            syncing = true;

            try {
                have.filter((value) => !want.includes(value)).forEach((value) => instance.unselect(value));
                want.filter((value) => !have.includes(value) && instance.hasItem(value)).forEach((value) => instance.select(value));
            } finally {
                syncing = false;
                previous = [...instance.getState().selectedValues];
            }
        },

        /** Flexilla → Alpine : seul un choix de la personne change la valeur. */
        onState(state) {
            const next = state.selectedValues;

            if (!syncing) {
                const added = next.filter((value) => !previous.includes(value));
                // Une option désenregistrée par le filtre n'est pas désélectionnée.
                const removed = previous.filter((value) => !next.includes(value) && instance?.hasItem(value));

                if (added.length || removed.length) {
                    if (multiple) {
                        const kept = this.values.filter((value) => !removed.includes(value));

                        added.forEach((value) => kept.includes(value) || kept.push(value));
                        this.value = kept;

                        // Autocomplete multiple : le texte tapé a servi, place à la suivante.
                        if (isAutocomplete && added.length && this.query !== "") {
                            part("[data-autocomplete-id]").value = "";
                            this.query = "";
                            queueMicrotask(() => instance?.setSearch(""));
                        }
                    } else {
                        this.value = added.length ? added[added.length - 1] : null;
                    }
                }

                this.queueResync();
            }

            previous = [...next];

            if (state.open !== wasOpen) {
                wasOpen = state.open;
                state.open ? this.onOpen() : this.onClose();
            }
        },

        queueResync() {
            if (resyncQueued) {
                return;
            }

            resyncQueued = true;

            queueMicrotask(() => {
                resyncQueued = false;
                this.push();
            });
        },

        onOpen() {
            const content = part("[data-select-content]");
            const search = !isAutocomplete && content.querySelector("[data-select-input]");

            // Le panneau s'ouvre sur l'option choisie, pas sur la première.
            const selected = instance.getState().items.findIndex((item) => this.values.includes(item.value));

            if (selected >= 0) {
                instance.highlight(selected);

                // Ouvert au clavier, Flexilla a mis le focus sur la première option.
                setTimeout(() => {
                    const value = instance?.getState().items[selected]?.value ?? "";
                    const option = content.querySelector(`[data-select-item="${CSS.escape(value)}"]`);

                    if (!search && option && content.contains(document.activeElement) && document.activeElement !== option) {
                        focusWhenShown(() => option);
                    }
                });
            }

            if (search) {
                focusWhenShown(() => search);
            }
        },

        onClose() {
            // Le listbox rouvre sur toute la liste.
            const search = !isAutocomplete && part("[data-select-content] [data-select-input]");

            if (search && search.value !== "") {
                search.value = "";
                instance?.setSearch("");
            }
        },
    };
}

export function LayerPlugin(Alpine) {
    Alpine.directive("fw-layer", (el) => {
        // _x_teleportBack : le <template x-teleport> d'où vient ce panneau.
        const dialog = el._x_teleportBack?.closest?.("dialog");

        if (dialog && el.parentElement !== dialog) {
            dialog.append(el);
        }
    });
}
